#!/usr/bin/env python3
"""Fill an HWPX template (ZIP of XML files) with JSON data.

This script:
- Loads /root/project_proposal.json
- Replaces {{placeholders}} in extracted template XML files
- Normalizes budget formatting
- Appends month spans to phase (단계1/2/3) lines
- Removes stale layout cache elements (e.g., hp:linesegarray) from modified paragraphs
- Repacks the directory into /root/project_proposal_ready.hwpx
"""

from __future__ import annotations

import json
import os
import re
import sys
import zipfile
import xml.etree.ElementTree as ET
from typing import Dict, Iterable, List, Optional, Tuple


HWPML_NS = "http://www.hancom.co.kr/hwpml/2010/HWPML"
ET.register_namespace("hp", HWPML_NS)


PLACEHOLDER_RE = re.compile(r"\{\{([^{}]+)\}\}")


def localname(tag: str) -> str:
    if "}" in tag:
        return tag.split("}", 1)[1]
    return tag


def normalize_budget(value: str) -> str:
    # Requirement: remove commas but keep leading currency symbol.
    if not isinstance(value, str):
        value = str(value)
    if value.startswith("₩"):
        return "₩" + value[1:].replace(",", "")
    return value.replace(",", "")


def months_inclusive(sy: int, sm: int, ey: int, em: int) -> int:
    return (ey - sy) * 12 + (em - sm + 1)


def parse_month_span(text: str) -> Optional[int]:
    """Extract a (N개월) month span from a date range inside the phase text.

    Supports patterns commonly seen in our JSON/template:
    - (YYYY.MM ~ YYYY.MM)
    - (YYYY-MM ~ YYYY-MM)
    - (YYYY.MM) / (YYYY-MM)
    """

    # Prefer explicit ranges first
    m = re.search(r"(\d{4})[.\-](\d{2})\s*~\s*(\d{4})[.\-](\d{2})", text)
    if m:
        sy, sm, ey, em = map(int, m.groups())
        return months_inclusive(sy, sm, ey, em)

    # Single month in parentheses: (YYYY.MM) or (YYYY-MM)
    m = re.search(r"\((\d{4})[.\-](\d{2})\)", text)
    if m:
        sy, sm = map(int, m.groups())
        return months_inclusive(sy, sm, sy, sm)

    # Also allow without parentheses (defensive)
    m = re.search(r"(\d{4})[.\-](\d{2})", text)
    if m:
        sy, sm = map(int, m.groups())
        return months_inclusive(sy, sm, sy, sm)

    return None


def should_remove_cache_element(tag: str) -> bool:
    ln = localname(tag).lower()
    # HWPX stores line segmentation / charshape caches that become stale.
    return (
        "lineseg" in ln
        or ln == "linesegarray"
        or ln == "linesegarray"  # variant casing handled by lower()
        or "charshapearray" in ln
    )


def iter_modified_text_nodes(root: ET.Element) -> Iterable[ET.Element]:
    # HWPX text nodes are typically hp:t within hp:run within hp:p.
    for el in root.iter():
        if localname(el.tag) == "t":
            yield el


def find_parent_map(root: ET.Element) -> Dict[ET.Element, ET.Element]:
    return {child: parent for parent in root.iter() for child in parent}


def remove_layout_cache_from_paragraph(p_el: ET.Element) -> int:
    """Remove layout-cache descendant elements within a paragraph."""
    parent_map = find_parent_map(p_el)
    to_remove: List[ET.Element] = []
    for el in list(p_el.iter()):
        if el is p_el:
            continue
        if should_remove_cache_element(el.tag):
            to_remove.append(el)

    removed = 0
    for el in to_remove:
        parent = parent_map.get(el)
        if parent is not None:
            parent.remove(el)
            removed += 1
    return removed


def replace_placeholders_in_text(text: str, data: Dict[str, str]) -> Tuple[str, bool]:
    """Replace all {{key}} placeholders in a string.

    Returns (new_text, changed).
    """

    changed = False

    def repl(m: re.Match) -> str:
        nonlocal changed
        key = m.group(1).strip()
        if key not in data:
            raise KeyError(f"No JSON value for placeholder: {key}")
        val = data[key]
        if key == "예산":
            val = normalize_budget(val)
        changed = True
        return str(val)

    new_text = PLACEHOLDER_RE.sub(repl, text)
    return new_text, changed


def append_month_span_if_phase_line(text: str) -> Tuple[str, bool]:
    """If this is a 단계 line, append (N개월) computed from its date range."""

    # Only apply to the phase lines, per requirements.
    if not re.search(r"\b[123]단계\b", text):
        return text, False

    # Avoid double-appending.
    if re.search(r"\(\d+개월\)\s*$", text):
        return text, False

    months = parse_month_span(text)
    if months is None:
        return text, False

    return f"{text} ({months}개월)", True


def process_xml_file(path: str, data: Dict[str, str]) -> bool:
    """Process a single XML file. Returns True if modified."""

    tree = ET.parse(path)
    root = tree.getroot()

    modified_paragraphs: set[ET.Element] = set()

    parent_map = find_parent_map(root)

    # 1) Replace placeholders in hp:t nodes
    for t_el in iter_modified_text_nodes(root):
        if t_el.text and "{{" in t_el.text:
            new_text, changed = replace_placeholders_in_text(t_el.text, data)
            if changed and new_text != t_el.text:
                t_el.text = new_text
                # find enclosing paragraph (<hp:p>)
                p = t_el
                while p is not None and localname(p.tag) != "p":
                    p = parent_map.get(p)
                if p is not None:
                    modified_paragraphs.add(p)

    # 2) Append month spans to phase lines (after replacements)
    for t_el in iter_modified_text_nodes(root):
        if t_el.text and re.search(r"\b[123]단계\b", t_el.text):
            new_text, changed = append_month_span_if_phase_line(t_el.text)
            if changed and new_text != t_el.text:
                t_el.text = new_text
                p = t_el
                while p is not None and localname(p.tag) != "p":
                    p = parent_map.get(p)
                if p is not None:
                    modified_paragraphs.add(p)

    # 3) Remove stale layout-cache elements from modified paragraphs
    for p in modified_paragraphs:
        remove_layout_cache_from_paragraph(p)

    # Ensure no placeholders remain in this file
    xml_bytes = ET.tostring(root, encoding="utf-8", xml_declaration=True)
    if b"{{" in xml_bytes:
        raise RuntimeError(f"Placeholders remain after processing: {path}")

    # Write back (preserve declaration/encoding)
    with open(path, "wb") as f:
        f.write(xml_bytes)

    return bool(modified_paragraphs)


def zip_dir(src_dir: str, out_path: str) -> None:
    """Create a .hwpx ZIP from a directory (paths relative to src_dir)."""

    # Mirror common OPC convention: store mimetype first and uncompressed if present.
    mimetype_path = os.path.join(src_dir, "mimetype")

    with zipfile.ZipFile(out_path, "w") as z:
        if os.path.isfile(mimetype_path):
            z.write(mimetype_path, arcname="mimetype", compress_type=zipfile.ZIP_STORED)

        for dirpath, _, filenames in os.walk(src_dir):
            for fn in filenames:
                full = os.path.join(dirpath, fn)
                rel = os.path.relpath(full, src_dir)
                if rel == "mimetype":
                    continue
                z.write(full, arcname=rel, compress_type=zipfile.ZIP_DEFLATED)


def main() -> int:
    extracted_dir = "/tmp/hwpx_work/template_extracted"
    json_path = "/root/project_proposal.json"
    out_hwpx = "/root/project_proposal_ready.hwpx"

    with open(json_path, "r", encoding="utf-8") as f:
        data = json.load(f)

    # Find files containing placeholders
    xml_files: List[str] = []
    for dirpath, _, filenames in os.walk(extracted_dir):
        for fn in filenames:
            if not fn.lower().endswith(".xml"):
                continue
            path = os.path.join(dirpath, fn)
            with open(path, "rb") as xf:
                if b"{{" in xf.read():
                    xml_files.append(path)

    if not xml_files:
        raise RuntimeError("No XML files with placeholders found")

    modified_any = False
    for path in sorted(xml_files):
        modified = process_xml_file(path, data)
        modified_any = modified_any or modified

    # Final safety check across extracted tree
    for dirpath, _, filenames in os.walk(extracted_dir):
        for fn in filenames:
            if not fn.lower().endswith(".xml"):
                continue
            path = os.path.join(dirpath, fn)
            with open(path, "rb") as xf:
                if b"{{" in xf.read():
                    raise RuntimeError(f"Placeholders remain in: {path}")

    zip_dir(extracted_dir, out_hwpx)
    return 0


if __name__ == "__main__":
    try:
        raise SystemExit(main())
    except Exception as e:
        print(f"ERROR: {e}", file=sys.stderr)
        raise

