    """If this is a 단계 line, append (N개월) computed from its date range."""

    # Only apply to the phase lines, per requirements.
    if not re.search(r"\b[123]단계\b", text):
        return text, False

    # Avoid double-appending.
    if re.search(r"\(\d+개월\)\s*$", text):
        return text, False

    months = parse_month_span(text)
    if months is None:
        return text, False

    return f"{text} ({months}개월)", True


